        String publicKeyStr = Base64.getEncoder().encodeToString(keyPair.getPublicKey());
        System.out.println("Public Key: " + publicKeyStr);

        byte[] signature = keyPair.sign("Hello World!".getBytes());

        boolean isValid = keyPair.verify("Hello World!".getBytes(), signature);
        System.out.println("Is Valid? " + isValid);
    }

    public static KeyPair generateKeyPair() throws Exception {
        KeyPairGenerator kpg = KeyPairGenerator.getInstance("HmacSHA512");
        kpg.initialize(128);

        return new KeyPair(kpg.generateKeyPair().getPrivate(), kpg.generateKeyPair().getPublic());
    }
